const {chromium}=require('playwright');const assert=require('node:assert/strict');const fs=require('node:fs');
const routes=["app/dashboard", "app/vendors", "app/pos", "app/sales", "app/purchases", "app/purchases/new", "app/products", "app/parties", "app/expenses", "app/finance", "app/reconciliation", "app/daybook", "app/audit-ledger", "app/accounts", "app/reports", "app/warranty", "app/quotations", "app/online-sales", "app/notifications", "app/subscription", "app/support", "app/settings/business", "app/settings/sales", "app/settings/products", "app/settings/purchases", "app/settings/money", "app/settings/invoices", "app/settings/team", "app/settings/notifications", "app/settings/personal", "app/settings/data", "saas/overview", "saas/tenants", "saas/tenants/t1", "saas/plans", "saas/subscriptions", "saas/invoices", "saas/invoices/SAAS-1001", "saas/payments", "saas/payments/PAY-1001", "saas/sms", "saas/services", "saas/services/ORD-1001", "saas/support", "saas/support/TKT-1001", "saas/knowledge", "saas/announcements", "saas/reports", "saas/audit", "saas/team", "saas/settings"];
async function main(){const {createServer}=await import('vite');const server=await createServer({server:{host:'127.0.0.1',port:4299,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});const results=[];
try{for(const size of [{width:390,height:844},{width:768,height:1024},{width:1024,height:768},{width:1440,height:900}])for(const theme of ['light','dark']){const context=await browser.newContext({viewport:size,colorScheme:theme,hasTouch:size.width<1440,reducedMotion:'reduce'});const page=await context.newPage();let errors=[];page.on('pageerror',error=>errors.push(error.message));
for(const route of routes){errors=[];await page.goto('http://127.0.0.1:4299/#/'+route);await page.locator('main').waitFor();await page.waitForTimeout(100);const geometry=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,overflow:[...document.querySelectorAll('main *')].filter(node=>{const r=node.getBoundingClientRect();return r.width&&r.right>innerWidth+2&&!node.closest('.overflow-x-auto,.overflow-auto')}).slice(0,5).map(node=>({tag:node.tagName,className:String(node.className),text:node.textContent.slice(0,70)}))}));results.push({route,...size,theme,...geometry,errors});}
await context.close();console.log(size.width,theme,'checked');}
if(process.env.AUDIT_OUTPUT)fs.writeFileSync(process.env.AUDIT_OUTPUT,JSON.stringify(results,null,2));const failures=results.filter(row=>row.scroll>row.width+2||row.errors.length);assert.deepEqual(failures,[],'route errors or whole-page overflow');console.log(results.length+' project route renders passed; four device sizes, both themes, touch at phone/tablet');
}finally{await browser.close();await server.close();}}
main().catch(error=>{console.error(error);process.exitCode=1;});
